import React from 'react';
import { 
  Card, 
  Table, 
  Tag, 
  Typography, 
  Space,
  Alert
} from 'antd';
import { 
  BarChartOutlined,
  TrophyOutlined,
  DollarOutlined
} from '@ant-design/icons';
import { useQuery } from 'react-query';
import dayjs from 'dayjs';
import axios from 'axios';

const { Title, Text } = Typography;

const Analysis = () => {
  // Query para obtener resumen de análisis
  const {
    data: analysisData,
    isLoading,
    error
  } = useQuery(
    ['summary'],
    async () => {
      const response = await axios.get('/api/games/summary');
      return response.data;
    },
    {
      retry: 1,
    }
  );

  // Configuración de columnas para la tabla
  const columns = [
    {
      title: 'Fecha',
      dataIndex: 'game_date',
      key: 'game_date',
      width: 120,
      render: (date) => dayjs(date).format('DD/MM/YYYY'),
    },
    {
      title: 'Hora',
      dataIndex: 'game_time',
      key: 'game_time',
      width: 100,
      render: (time) => time ? dayjs(`2000-01-01 ${time}`).format('HH:mm') : '-',
    },
    {
      title: 'Partido',
      key: 'matchup',
      render: (_, record) => (
        <div>
          <Text strong>{record.home_team_name}</Text>
          <br />
          <Text type="secondary">vs</Text>
          <br />
          <Text strong>{record.away_team_name}</Text>
        </div>
      ),
    },
    {
      title: 'Probabilidad Local',
      dataIndex: 'home_probability',
      key: 'home_probability',
      width: 140,
      render: (prob) => (
        <Text strong style={{ color: prob > 60 ? '#52c41a' : prob > 50 ? '#faad14' : '#ff4d4f' }}>
          {prob.toFixed(1)}%
        </Text>
      ),
    },
    {
      title: 'Probabilidad Visitante',
      dataIndex: 'away_probability',
      key: 'away_probability',
      width: 140,
      render: (prob) => (
        <Text strong style={{ color: prob > 60 ? '#52c41a' : prob > 50 ? '#faad14' : '#ff4d4f' }}>
          {prob.toFixed(1)}%
        </Text>
      ),
    },
    {
      title: 'Línea Justa Local',
      dataIndex: 'home_american_odds',
      key: 'home_american_odds',
      width: 140,
      render: (odds) => (
        <Text style={{ color: odds > 0 ? '#52c41a' : '#ff4d4f' }}>
          {odds > 0 ? '+' : ''}{odds}
        </Text>
      ),
    },
    {
      title: 'Línea Justa Visitante',
      dataIndex: 'away_american_odds',
      key: 'away_american_odds',
      width: 140,
      render: (odds) => (
        <Text style={{ color: odds > 0 ? '#52c41a' : '#ff4d4f' }}>
          {odds > 0 ? '+' : ''}{odds}
        </Text>
      ),
    },
    {
      title: 'Nivel',
      dataIndex: 'level',
      key: 'level',
      width: 120,
      render: (level) => {
        const levelConfig = {
          diamond: { color: '#f5222d', text: 'Diamante', icon: <TrophyOutlined /> },
          exclusive: { color: '#fa8c16', text: 'Exclusivo', icon: <DollarOutlined /> },
          vip: { color: '#1890ff', text: 'VIP', icon: <BarChartOutlined /> },
        };
        const config = levelConfig[level] || { color: 'default', text: level };
        return (
          <Tag color={config.color} icon={config.icon}>
            {config.text}
          </Tag>
        );
      },
    },
  ];

  const analysis = analysisData?.data || [];

  return (
    <div className="analysis-page">
      <Card>
        <div style={{ marginBottom: 16 }}>
          <Title level={2}>
            <BarChartOutlined /> Análisis de Partidos
          </Title>
          <Text type="secondary">
            Resultados de análisis con modelo de 5 factores
          </Text>
        </div>

        {error && (
          <Alert
            message="Error"
            description={error.message}
            type="error"
            showIcon
            style={{ marginBottom: 16 }}
          />
        )}

        {isLoading ? (
          <div style={{ textAlign: 'center', padding: '50px' }}>
            <Text>Cargando análisis...</Text>
          </div>
        ) : (
          <>
            {analysis.length === 0 ? (
              <Alert
                message="No hay análisis"
                description="No se encontraron análisis de partidos. Ve a la página de inicio para analizar partidos."
                type="info"
                showIcon
              />
            ) : (
              <Table
                columns={columns}
                dataSource={analysis}
                rowKey="id"
                pagination={{
                  pageSize: 10,
                  showSizeChanger: true,
                  showQuickJumper: true,
                  showTotal: (total, range) => 
                    `${range[0]}-${range[1]} de ${total} análisis`,
                }}
                size="middle"
                scroll={{ x: 1200 }}
              />
            )}
          </>
        )}

        {analysis.length > 0 && (
          <div style={{ marginTop: 16, textAlign: 'center' }}>
            <Space>
              <Text type="secondary">
                Total de análisis: {analysis.length}
              </Text>
              <Text type="secondary">
                • Diamante: {analysis.filter(a => a.level === 'diamond').length}
              </Text>
              <Text type="secondary">
                • Exclusivo: {analysis.filter(a => a.level === 'exclusive').length}
              </Text>
              <Text type="secondary">
                • VIP: {analysis.filter(a => a.level === 'vip').length}
              </Text>
            </Space>
          </div>
        )}
      </Card>
    </div>
  );
};

export default Analysis;
